choose.when:
AND p.status = 'PENDING'


        AND p.id IN #{aid}

    AND false

mapper.sql:
WHERE true


    AND p.status IN #{st}

AND (rq.returned_qty - rq.defect_qty > 0) = #{q.returned}


        AND r.late
        AND r.near
        AND r.node_late
        AND r.issue
        AND r.upstream
        AND (r.late OR r.node_late)
        AND false




        AND p.status = 'RUNNING'
        AND p.status = 'APPROVED'
        AND r.near
        AND r.late
        AND r.node_late
        AND r.issue
        AND false


AND COALESCE(p.expect_date, p.due_date) >= #{q.dueDateFrom}
AND COALESCE(p.expect_date, p.due_date) <= #{q.dueDateTo}

    AND p.id IN #{id}


    AND o.no IN #{no}


    AND p.style_id IN #{sid}





    AND p.id IN (
        SELECT kp.id FROM prd_order kp WHERE upper(kp.no) LIKE #{keywordCode}

            OR upper(kp.no) IN #{code}

        UNION
        SELECT kp.id FROM ord_order ko JOIN prd_order kp ON kp.order_id = ko.id
        WHERE upper(ko.no) LIKE #{keywordCode}

            OR upper(ko.no) IN #{code}

        UNION
        SELECT kp.id FROM sty_style ks JOIN prd_order kp ON kp.style_id = ks.id
        WHERE upper(ks.code) LIKE #{keywordCode} OR ks.name ILIKE #{keywordContains}

            OR upper(ks.code) IN #{code}

        UNION
        SELECT kp.id FROM sup_supplier kf JOIN prd_order kp ON kp.factory_id = kf.id
        WHERE kf.name ILIKE #{keywordContains} OR kf.short_name ILIKE #{keywordContains}
    )

mapper.select:
SELECT r.late, r.near, r.node_late, r.issue, r.upstream
FROM prd_order p

WHERE p.id = #{id}

SELECT p.id, p.no, p.kind, p.status, p.factory_id, f.short_name AS factory_short_name, s.code AS style_code,
       s.name AS style_name, p.total_qty, p.issue_status
FROM prd_order p
JOIN sup_supplier f ON f.id = p.factory_id
JOIN sty_style s ON s.id = p.style_id
WHERE p.issue_status IS NOT NULL

    AND p.status IN ('APPROVED', 'RUNNING', 'DONE') AND p.issue_status IN ('PARTIAL', 'DONE')
    AND p.status IN ('APPROVED', 'RUNNING') AND p.issue_status IN ('NONE', 'PARTIAL')

AND (p.create_by = #{scope.userId} OR p.merch_id = #{scope.userId})
AND p.product_line = ANY(#{scope.lines.values, typeHandler=com.lingmao.scm.common.mybatis.StringArrayTypeHandler})
AND p.factory_id = #{q.factoryId}




    AND p.id IN (
        SELECT kp.id FROM prd_order kp WHERE upper(kp.no) LIKE #{keywordCode}

            OR upper(kp.no) IN #{code}

        UNION
        SELECT kp.id FROM sty_style ks JOIN prd_order kp ON kp.style_id = ks.id
        WHERE upper(ks.code) LIKE #{keywordCode}

            OR upper(ks.code) IN #{code}

        UNION
        SELECT kp.id FROM sup_supplier kf JOIN prd_order kp ON kp.factory_id = kf.id
        WHERE kf.name ILIKE #{keywordContains} OR kf.short_name ILIKE #{keywordContains}
    )

ORDER BY p.id DESC
